query:
SELECT DISTINCT ?company ?companyLabel ?companyDescription ?industry ?industryLabel
WHERE {
  { SELECT ?company ?industry WHERE { VALUES ?type { wd:Q783794 wd:Q4830453 wd:Q891723 } ?company wdt:P31 ?type; wdt:P452 ?industry. } LIMIT 20000 }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
